/// </summary>
internal final class AVAProdSetupReleaseRecordService  extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "_contract">AVAProdSetupReleaseRecordContract</param>
public void process(AVAProdSetupReleaseRecordContract _contract)
{
    AVAProdSetupReleaseProtocol protocol;
    AVAProdSetupRelease prodSetupRelease;
    ProdId ProdId = _contract.parmProdId();
    avacheckcode checkCode = _contract.parmCheckCode();
    const Name checkAttr = "@NDX:NXAOK";

    if (ProdId && checkCode)
    {
        protocol.selectForUpdate();
        prodSetupRelease = AVAProdSetupRelease::find(checkCode);
        if (prodSetupRelease)
        {
            ttsbegin;
            protocol.ProdId = ProdId;
            protocol.CheckCode = checkCode;
            protocol.Responsible = prodSetupRelease.Responsible;
            protocol.ProdCheckProcess = prodSetupRelease.ProdCheckProcess;
            protocol.DateTimeExecuted = DateTimeUtil::getSystemDateTime();
            protocol.CheckAttribute = checkAttr;
            protocol.insert();
            ttscommit;
        }
    }
}
